import type { ChartOptions } from 'chart.js';
import {
  CHART_CONSTANTS,
  COLORS,
} from 'components/Chart/Bar/SimpleBarChart/constants/constants';

import {
  POS_CHART_LAYOUT_PAD_LEFT_PX,
  POS_CHART_LAYOUT_PAD_RIGHT_PX,
  POS_CHART_LAYOUT_TOP_PX,
  POS_CHART_Y_AXIS_WIDTH_PX,
} from '../constants';

type YScaleExtents = {
  min: number;
  max: number;
};

export function buildPosPerformanceChartOptions(
  yScaleExtents: YScaleExtents,
): ChartOptions<'bar'> {
  return {
    responsive: true,
    maintainAspectRatio: false,
    indexAxis: 'x',
    borderColor: COLORS.WHITE,
    datasets: {
      bar: {
        categoryPercentage: 0.68,
        barPercentage: 0.84,
      },
    },
    layout: {
      padding: {
        top: POS_CHART_LAYOUT_TOP_PX,
        bottom: 10,
        left: POS_CHART_LAYOUT_PAD_LEFT_PX,
        right: POS_CHART_LAYOUT_PAD_RIGHT_PX,
      },
    },
    plugins: {
      legend: {
        display: false,
      },
      zeroLabel: { display: true },
      extendYAxis: { display: false },
      extendXAxis: { display: false },
      tooltip: { enabled: false },
      datalabels: {
        clamp: false,
        display: true,
        font: {
          family: CHART_CONSTANTS.FONT_FAMILY,
          size: 10,
          weight: 'normal',
        },
        color: COLORS.BLACK,
        anchor: (context) => {
          const value = context.dataset.data[context.dataIndex] as number;
          return value < 0 ? 'start' : 'end';
        },
        align: (context) => {
          const value = context.dataset.data[context.dataIndex] as number;
          return value < 0 ? 'bottom' : 'top';
        },
        offset: 4,
        formatter: (value: number) => {
          if (value === null || value === Number.EPSILON) return '';
          return `${value.toFixed(1)}%`;
        },
      },
    },
    scales: {
      x: {
        grid: {
          display: false,
          drawOnChartArea: false,
          tickWidth: 0,
        },
        offset: true,
        border: {
          display: false,
        },
        ticks: {
          autoSkip: false,
          font: {
            weight: 'normal',
            size: CHART_CONSTANTS.FONT_SIZE,
            family: CHART_CONSTANTS.FONT_FAMILY,
            lineHeight: 1.1,
          },
          color: COLORS.BLACK_OPACITY,
          padding: 4,
          align: 'center',
          display: true,
        },
      },
      y: {
        offset: false,
        display: true,
        border: { display: false },
        grid: {
          display: false,
        },
        beginAtZero: true,
        min: yScaleExtents.min,
        max: yScaleExtents.max,
        ticks: {
          display: false,
        },
        afterFit: (axis) => {
          axis.width = POS_CHART_Y_AXIS_WIDTH_PX;
        },
      },
    },
  };
}
